      SUBROUTINE SOLENCC     EVALUATES TRANSFER MATRIX FOR A SOLENOIDCC ----------------------------------------------------------------------      INCLUDE 'BETAC.CIN'      INCLUDE 'ELM0B.CIN'      INCLUDE 'ELM1A.CIN'      INCLUDE 'ELM5B.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'ELM19.CIN'      INCLUDE 'R.CIN'C      SN = SIN(KL)      CS = COS(KL)      R(4,4) = 0.5 + 0.5*CS      R(3,3) = R(4,4)      R(2,2) = R(4,4)      R(1,1) = R(4,4)      R(1,4) = (1.- CS)/KO      R(3,2) = - R(1,4)      R(4,1) = 0.25*KO*(1.- CS)      R(2,3) = - R(4,1)      R(4,2) = - 0.5*SN      R(3,1) = R(4,2)      R(2,4) = - R(3,1)      R(1,3) = R(2,4)      R(3,4) = R(1,3)*2./KO      R(1,2) = R(3,4)      R(4,3) = - 0.25*KO*SN      R(2,1) = R(4,3)      IF (SM .NE. 0.0 .AND. RI .NE. 0.0) R(5,6) = L/GAMMA**2      RETURN      END